def _match(obj, selector: str) -> bool:
    labels = getattr(obj.metadata, "labels", {}) or {}
    for part in selector.split(","):
        if "=" in part:
            k, v = part.split("=", 1)
            if labels.get(k) != v:
                return False
    return True


